import { memo, useCallback, useMemo } from 'react';

import { useIntl } from 'react-intl';

import {
  Icon,
  Select,
  SizableText,
  XStack,
  YStack,
} from '@onekeyhq/components';
import type { ISelectItem } from '@onekeyhq/components';
import type { IBBOPriceMode } from '@onekeyhq/kit/src/states/jotai/contexts/hyperliquid';
import { OneKeyLocalError } from '@onekeyhq/shared/src/errors/errors/localError';
import { ETranslations } from '@onekeyhq/shared/src/locale';

import { formatBboModeLabel } from './bboDisplay';

interface IBBOSelectorProps {
  value: IBBOPriceMode;
  onChange: (mode: IBBOPriceMode) => void;
  disabled?: boolean;
  isMobile?: boolean;
  inputLike?: boolean;
}

export const BBOSelector = memo<IBBOSelectorProps>(
  // eslint-disable-next-line react/prop-types
  ({
    value,
    onChange,
    disabled = false,
    isMobile = false,
    inputLike = false,
  }) => {
    const intl = useIntl();

    const bboOptions = useMemo((): ISelectItem[] => {
      const counterpartyLabel = intl.formatMessage({
        id: ETranslations.Perps_BBO_Counterparty,
      });
      const queueLabel = intl.formatMessage({
        id: ETranslations.Perps_BBO_Queue,
      });

      return [
        {
          label: formatBboModeLabel(counterpartyLabel, 0),
          value: 'counterparty-0',
        },
        {
          label: formatBboModeLabel(counterpartyLabel, 5),
          value: 'counterparty-5',
        },
        {
          label: formatBboModeLabel(queueLabel, 0),
          value: 'queue-0',
        },
        {
          label: formatBboModeLabel(queueLabel, 5),
          value: 'queue-5',
        },
      ];
    }, [intl]);

    const parseBBOPriceMode = useCallback((val: string): IBBOPriceMode => {
      const parts = val.split('-');
      if (parts.length !== 2) {
        throw new OneKeyLocalError({
          message: `[BBOSelector] Invalid BBO mode format: ${val}`,
        });
      }
      const [type, offsetTicksStr] = parts;
      const offsetTicks = parseInt(offsetTicksStr, 10);
      if (
        (type !== 'counterparty' && type !== 'queue') ||
        (offsetTicks !== 0 && offsetTicks !== 5)
      ) {
        throw new OneKeyLocalError({
          message: `[BBOSelector] Invalid BBO mode: type=${type}, offsetTicks=${offsetTicks}`,
        });
      }
      return { type, offsetTicks } as IBBOPriceMode;
    }, []);

    const serializeBBOPriceMode = useCallback(
      (mode: IBBOPriceMode): string | undefined => {
        if (!mode) return undefined;
        return `${mode.type}-${mode.offsetTicks}`;
      },
      [],
    );

    const handleChange = useCallback(
      (val: string | undefined) => {
        if (!val) {
          onChange(null);
          return;
        }
        const mode = parseBBOPriceMode(val);
        onChange(mode);
      },
      [onChange, parseBBOPriceMode],
    );

    const currentValue = serializeBBOPriceMode(value);
    const containerBg = inputLike ? '$bgStrong' : '$bgSubdued';

    if (isMobile) {
      return (
        <YStack
          bg={containerBg}
          borderRadius="$2"
          borderWidth="$px"
          borderColor="$transparent"
          px="$3"
          gap="$3"
        >
          <Select
            testID="perp-current-value-select"
            items={bboOptions}
            value={currentValue}
            onChange={handleChange}
            disabled={disabled}
            title={intl.formatMessage({
              id: ETranslations.Perps_BBO_select_title,
            })}
            renderTrigger={({ onPress, label, disabled: disabledTrigger }) => (
              <XStack
                onPress={onPress}
                disabled={disabledTrigger}
                h={36}
                alignItems="center"
                justifyContent="space-between"
                cursor="default"
              >
                <SizableText size="$bodyMdMedium" color="$text">
                  {label}
                </SizableText>
                <Icon
                  name="ChevronTriangleDownSmallSolid"
                  color="$iconSubdued"
                  size="$4"
                />
              </XStack>
            )}
            placement="bottom-end"
            floatingPanelProps={{
              width: 160,
            }}
          />
        </YStack>
      );
    }

    return (
      <Select
        testID="perp-select"
        items={bboOptions}
        value={currentValue}
        onChange={handleChange}
        disabled={disabled}
        title={intl.formatMessage({
          id: ETranslations.Perps_BBO_select_title,
        })}
        renderTrigger={({ onPress, label, disabled: disabledTrigger }) => (
          <YStack
            bg={containerBg}
            borderRadius="$3"
            py="$1"
            pl="$1"
            borderWidth="$px"
            borderColor="$transparent"
            onPress={onPress}
            disabled={disabledTrigger}
            cursor="default"
            hoverStyle={{
              borderColor: '$border',
            }}
          >
            <XStack
              h={32}
              alignItems="center"
              justifyContent="space-between"
              px="$2"
            >
              <SizableText size="$bodyMd" color="$textSubdued">
                {intl.formatMessage({
                  id: ETranslations.perp_orderbook_price,
                })}
              </SizableText>
              <XStack alignItems="center" gap="$1" justifyContent="flex-end">
                <SizableText size="$bodyMdMedium" color="$text">
                  {label}
                </SizableText>
                <Icon
                  name="ChevronDownSmallOutline"
                  color="$iconSubdued"
                  size="$4"
                />
              </XStack>
            </XStack>
          </YStack>
        )}
        placement="bottom-end"
        floatingPanelProps={{
          width: 160,
        }}
      />
    );
  },
);

BBOSelector.displayName = 'BBOSelector';
